md=['# RV1106开发平台辨认与图片尺寸归档｜2026-10-09','> 涛哥回复：倾向使用1106，已采购开发板，预计过几天到。具体厂家/板型号/芯片后缀未知。用户明确：开发板只作开发平台，最终产品自研主板；不把平台板框当产品PCB或机身尺寸。','## 1. 可看图确认的候选','以下排序按外形分组，不表示采购概率。尺寸取官方文字/标注，不按照片像素测量。']
cards=[]
for r in records:
 g=r['group'];front='lubancat-board.jpg' if g=='lubancat' else g+'-front.jpg';back='lubancat-core.jpg' if g=='lubancat' else g+'-back.jpg';drawing=None if g=='lubancat' else g+'-drawing.jpg'
 md.extend([f'### {r["id"]} {r["name"]}',f'- 尺寸：{r["size"]}。',f'- 芯片/配置：{r["soc"]}。',f'- 辨认：{r["cue"]}',f'- 开发用途：{r["use"]}',f'- [厂家页面]({r["page"]}) · [产品原图](assets/{front}) · [背面/核心板图](assets/{back})'+(f' · [尺寸原图](assets/{drawing})' if drawing else ''),''])
